# Contraseñas: cambiar la propia y recuperarla por correo. Uso: python3 install12.py
import os,subprocess,sys,base64,shutil
API='/var/www/vibkaptur/public/api'; PRIV='/var/www/vibkaptur/private'
open('/tmp/_miclave.php','wb').write(base64.b64decode(''))
if subprocess.run(['php','-l','/tmp/_miclave.php'],capture_output=True).returncode!=0: print('FALLO de sintaxis. NO SE HA TOCADO NADA'); sys.exit(1)
ra=os.stat(os.path.join(API,'clave.php')); ru=os.stat(os.path.join(PRIV,'users.php'))
p=os.path.join(API,'miclave.php'); shutil.copyfile('/tmp/_miclave.php',p); os.chown(p,ra.st_uid,ra.st_gid); os.chmod(p,ra.st_mode&0o7777)
r=os.path.join(PRIV,'resets.json')
if not os.path.exists(r): open(r,'w').write('{}')
os.chown(r,ru.st_uid,ru.st_gid); os.chmod(r,0o600)
print('CONTRASEÑAS: CAMBIO Y RECUPERACION INSTALADOS')
